style.css:
/* General body styles */
body {
    background-color: #121212; /* Dark background */
    color: #e0e0e0; /* Light text color for contrast */
    font-family: 'Arial', sans-serif;
    margin: 0;
    padding: 0;
}

/* Link styling */
a {
    color: #1e90ff; /* Bright blue for links */
    text-decoration: none;
}

a:hover {
    text-decoration: underline; /* Underline on hover */
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
    color: #ffffff; /* White color for headings */
}

/* Paragraph styling */
p {
    color: #d3d3d3; /* Light gray text for paragraphs */
}

/* Button styling */
button {
    background-color: #333333; /* Dark background for buttons */
    color: #ffffff; /* White text */
    border: 1px solid #444444; /* Slightly lighter border */
    padding: 10px 20px;
    border-radius: 5px;
}

button:hover {
    background-color: #555555; /* Lighter background on hover */
}

/* Form input fields */
input, textarea {
    background-color: #1f1f1f; /* Dark background */
    color: #e0e0e0; /* Light text */
    border: 1px solid #444444; /* Border color */
    padding: 8px;
    border-radius: 5px;
}

/* Input field focus */
input:focus, textarea:focus {
    border-color: #1e90ff; /* Highlight border with blue when focused */
    outline: none;
}

/* Table styling */
table {
    width: 100%;
    border-collapse: collapse;
}

table th, table td {
    padding: 8px;
    border: 1px solid #444444;
    text-align: left;
}

table th {
    background-color: #333333; /* Dark background for table headers */
    color: #ffffff; /* White text */
}

table td {
    background-color: #1e1e1e; /* Dark background for table cells */
}

/* Links in tables */
table a {
    color: #1e90ff; /* Bright blue for table links */
}

/* Footer */
footer {
    background-color: #111111; /* Even darker background for the footer */
    color: #b0b0b0; /* Lighter gray for footer text */
    text-align: center;
    padding: 20px 0;
}
